package android.widget;
public class OverScroller extends Scroller { public OverScroller(android.content.Context c) { super(c); } public OverScroller(android.content.Context c,android.view.animation.Interpolator i) { super(c,i); } public OverScroller(android.content.Context c,android.view.animation.Interpolator i,boolean f) { super(c,i,f); } public void fling(int sx,int sy,int vx,int vy,int minX,int maxX,int minY,int maxY,int overX,int overY) { fling(sx,sy,vx,vy,minX,maxX,minY,maxY); } public boolean springBack(int sx,int sy,int minX,int maxX,int minY,int maxY) { int x=Math.max(minX,Math.min(maxX,sx)), y=Math.max(minY,Math.min(maxY,sy)); if(x==sx && y==sy) return false; startScroll(sx,sy,x-sx,y-sy); return true; } public boolean isOverScrolled() { return false; } public void notifyHorizontalEdgeReached(int start,int end,int over) {} public void notifyVerticalEdgeReached(int start,int end,int over) {} }
